# פרק 15 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=15
TITLE='ביטוח ונזקי גוף'
SUM=[' <p>רוב נזקי הגוף בישראל נדונים במשטרים מיוחדים של אחריות מוחלטת וביטוח חובה, ולא כרשלנות "רגילה".</p> <h3>15.1 פלת"ד — אחריות מוחלטת</h3> <p><strong>חוק הפיצויים לנפגעי תאונות דרכים (פלת"ד), התשל"ה–1975</strong> קובע <strong>אחריות מוחלטת</strong> (<strong>סעיף 2</strong>): הנפגע זכאי לפיצוי על נזקי גוף מתאונת דרכים <strong>ללא צורך להוכיח אשם</strong>. בתמורה — תקרות וכללי חישוב אחידים.</p> <h3>15.2 ייחוד העילה — סעיף 8</h3> <p>מי שעילתו לפי הפלת"ד אינו רשאי לתבוע על אותו נזק לפי פקודת הנזיקין — החוק הוא ה<strong>מסלול הבלעדי</strong> לנזקי גוף מתאונת דרכים.</p> <h3>15.3 ביטוח חובה ו"קרנית"</h3> <p>חובה לבטח כל רכב (ביטוח חובה). נפגע שאין לו ממי להיפרע (נהג לא מבוטח/לא מזוהה) — נפרע מ<strong>"קרנית"</strong> (הקרן לפיצוי נפגעי תאונות דרכים). המודל מגשים את תכלית <strong>פיזור הנזק</strong> והבטחת פיצוי מהיר וודאי, על חשבון ויתור על בירור אשם.</p> <h3>15.4 נקודות מפתח למבחן</h3> <ul><li>פלת"ד — אחריות מוחלטת ללא אשם (ס׳ 2).</li><li>ייחוד העילה — מסלול בלעדי (ס׳ 8).</li><li>ביטוח חובה + "קרנית"; פיזור הנזק.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('חוק הפיצויים לנפגעי תאונות דרכים, התשל"ה-1975', '', 'אחריות מוחלטת (ס׳ 2) לנזקי גוף מתאונת דרכים — פיצוי ללא הוכחת אשם, בתמורה לתקרות וכללי חישוב אחידים.'), ("ס' 8 — ייחוד עילה", '', 'מי שעילתו לפי הפלת"ד אינו רשאי לתבוע על אותו נזק לפי פקודת הנזיקין — מסלול בלעדי.'), ('ביטוח חובה ו"קרנית"', '', 'חובת ביטוח לכל רכב; "קרנית" משמשת רשת ביטחון לנפגע מנהג לא מבוטח או לא מזוהה.'), ('רע״א 3762/11 עיזבון רחימי נ׳ חריזי', 'פעוטה נשכחה וננעלה ברכב במשך זמן רב, ונפטרה. נדונה השאלה אם המאורע הוא "תאונת דרכים" שחוק הפלת״ד חל עליו (ההחלטה ניתנה בינואר 2012).', 'נקבע שהמאורע אינו תאונת דרכים. הנזק לא נגרם עקב שימוש ברכב למטרות תחבורה. הרכב היה רק המקום שבו אירע הנזק, ולא התממש בו סיכון תחבורתי.'), ('רע״א 2072/16 פלוני נ׳ שירביט', 'נדונה השאלה מתי תאונה נחשבת לתאונה שנגרמה "במתכוון", למשל כשנהג פוגע באדם בעת שהוא נמלט (ההחלטה ניתנה ביוני 2016).', 'תאונה נחשבת לתאונה שנגרמה במתכוון בכל מקרה שבו הנהג הפוגע ידע שהוא עתיד לפגוע בנפגע, גם אם מטרתו העיקרית הייתה אחרת, כמו להימלט, ולא רצה לפגוע בו. לסיווג יש השלכות על החריג לייחוד העילה ועל שלילת זכאות.'), ('ע״א 2591/09 אלנסארה נ׳ שליסל', 'נהג שנהג בלי ביטוח חובה, ולכן אינו זכאי לפיצוי לפי חוק הפלת״ד, נפגע בתאונה באשמת נהג אחר ותבע אותו לפי פקודת הנזיקין (פסק הדין ניתן בפברואר 2011).', 'מי שאין לו עילה לפי חוק הפלת״ד אינו כפוף לייחוד העילה, ורשאי לתבוע מזיק אשם לפי הפקודה. הפיצוי אינו מוגבל בתקרות החוק, אף שהתוצאה עלולה להיות טובה יותר מזו של נהג מבוטח. המחוקק שקל זאת ולא הגביל, וההמלצה לשנות זאת לא יושמה.'), ('דנ״א 5325/19 הכשרה חברה לביטוח נ׳ פיקאלי', 'דיון נוסף בשאלה מה דינו של נהג שנהג ברכב בניגוד למגבלת הגיל שבפוליסת ביטוח החובה (פסק הדין ניתן ביולי 2021).', 'ברוב דעות נקבע שאי־עמידה במגבלת הגיל שבפוליסה שוללת את הכיסוי הביטוחי לחלוטין לגבי אותו שימוש. זאת בניגוד להתניות "משניות" שהפסיקה סירבה לתת להן תוקף שולל. הנהג נחשב כמי שנהג כשהביטוח אינו מכסה את שימושו (ס׳ 7(5)).'), ('ע״א 709/80 פרלמן נ׳ לוזון, פ״ד לו(4) 273', 'דיון ביחס בין גמלאות שמשלם המוסד לביטוח לאומי לנפגע לבין הפיצויים שהנפגע תובע מהמזיק.', 'ס׳ 328 (בעבר ס׳ 150) מקנה למוסד זכות לתבוע מהמזיק את הגמלה ששילם או שישלם. הפסיקה פירשה את הזכות כתחלוף: זכות הנפגע בגין רכיב הגמלה עוברת למוסד. לכן מנכים את ערך הגמלאות מהפיצוי שהנפגע מקבל מהמזיק, וכך נמנע פיצוי כפל.'), ('ע״א 5690/98 מוניס נ׳ עאמר, פ״ד נו(3) 562', 'דיון בשאלה מי זכאי לפיצוי בגין טיפולים רפואיים שהנפגע קיבל בחינם מקופת החולים מכוח החוק.', 'בהמשך להלכת אלחדד נ׳ סהר נקבע ש"המקבל שירותים רפואיים בלא תשלום, בקופות החולים, מכוח החוק, אינו זכאי לתבוע מן המזיק פיצויים, בגין טיפולים רפואיים אלה, ואילו המיטיבה, קופת-החולים, זכאית לחזור על המזיק".')]
QS=[{'q': 'מהו העיקרון שביסוד חוק פיצויים לנפגעי תאונות דרכים?', 'o': ['פיצוי רק לנפגעים שאינם נהגים', 'ענישת נהגים רשלנים', 'פיצוי מהיר ובטוח לכל נפגע בלי תלות באשם, תמורת תקרות על הפיצוי וייחוד עילה', 'פיצוי מלא רק למי שהוכיח רשלנות'], 'c': 2, 'e': 'נכון. "לא הכל, אבל לכל": אחריות מוחלטת, ביטוח חובה וקרנית, ובמקביל תקרות וייחוד עילה.'}, {'q': 'הולך רגל חצה ברמזור אדום ונפגע מרכב שנהגו נסע בזהירות. האם הוא זכאי לפיצוי מלא לפי חוק הפלת״ד?', 'o': ['כן, אך בהפחתה של אשם תורם', 'לא, כי הולכי רגל אינם מכוסים בחוק', 'כן, האחריות מוחלטת ואין הפחתה בשל אשם תורם', 'לא, כי הנהג לא התרשל'], 'c': 2, 'e': 'נכון. לפי ס׳ 2(ג) האחריות "מוחלטת ומלאה", וס׳ 68 לפקודה אינו מוחל בחוק.'}, {'q': 'פעוטה נשכחה ברכב חונה ביום חם ונפטרה. האם זו "תאונת דרכים"?', 'o': ['לא, כי הנזק לא נגרם עקב שימוש ברכב למטרות תחבורה', 'כן, לפי החזקה של רכב שחנה במקום אסור', 'לא, כי מדובר במעשה מכוון', 'כן, כי הנזק אירע בתוך רכב מנועי'], 'c': 0, 'e': 'נכון. כך נקבע ברע״א 3762/11 עיזבון רחימי נ׳ חריזי.'}, {'q': 'אדם ירה בנהג במהלך נסיעתו, והנהג נפצע מהקליע. האם זו תאונת דרכים?', 'o': ['כן, כי הנפגע נהג באותה עת', 'לא, כי ירי אינו "מאורע"', 'לא, לפי החזקה הממעטת: הנזק נגרם ממעשה מכוון עצמו ולא מהשפעתו על השימוש ברכב', 'כן, אם הרכב היה מבוטח'], 'c': 2, 'e': 'נכון. אילו הנהג היה נבהל ומאבד שליטה ונפצע מההתנגשות, התוצאה עשויה להיות אחרת.'}, {'q': 'נפגע בתאונת דרכים, שהוכיח בבירור שהנהג האחר התרשל, מבקש לתבוע אותו לפי פקודת הנזיקין כדי לקבל פיצוי בלי תקרות. מה הדין?', 'o': ['אסור — ייחוד העילה (ס׳ 8) שולל תביעה לפי הפקודה, אלא אם התאונה נגרמה במתכוון על ידי אדם אחר', 'מותר, אם יוותר על התביעה לפי החוק', 'מותר רק נגד בעל הרכב', 'מותר, כי הוכחה רשלנות'], 'c': 0, 'e': 'נכון. זו לשון ס׳ 8(א), והחריג היחיד הוא תאונה שנגרמה במתכוון.'}, {'q': 'נהג שנסע בלי ביטוח חובה נפגע בתאונה באשמת נהג אחר. מה מצבו המשפטי?', 'o': ['זכאי לפיצוי לפי החוק, בהפחתה של 50%', 'זכאי לפיצוי מקרנית בלבד', 'אין לו כל זכות לפיצוי', 'אינו זכאי לפיצוי לפי חוק הפלת״ד, אך רשאי לתבוע את הנהג האשם לפי פקודת הנזיקין, בלי התקרות'], 'c': 3, 'e': 'נכון. ס׳ 7(5) שולל זכאות לפי החוק, ולכן ייחוד העילה אינו חל (אלנסארה נ׳ שליסל).'}, {'q': 'באילו מקרים מפצה קרנית לפי ס׳ 12(א)?', 'o': ['רק כשהנפגע הוא קטין', 'רק בתאונות בשטחים', 'כשהנוהג האחראי אינו ידוע, כשאין לו ביטוח או שהביטוח אינו מכסה, או כשהמבטח בפירוק', 'בכל תאונה שבה הנפגע מעדיף לתבוע את הקרן'], 'c': 2, 'e': 'נכון. אלה העילות שבס׳ 12(א), בהן פגע וברח ונהג לא מבוטח.'}, {'q': 'נהג בן 20 נהג ברכב, בעוד הפוליסה מגבילה את הנהיגה למי שמלאו לו 24. מה עמדת העליון בדנ״א 5325/19?', 'o': ['הנהג מבוטח אם הבעלים לא ידע על גילו', 'הכיסוי נשמר אך מופחת יחסית', 'ההפרה משנית, והכיסוי נשמר', 'אי־עמידה במגבלת הגיל שוללת לחלוטין את הכיסוי הביטוחי לגבי אותו שימוש'], 'c': 3, 'e': 'נכון. בדיון הנוסף (הכשרה נ׳ פיקאלי, 2021) נקבע שאין כיסוי. לגבי נפגעים צד שלישי תיכנס קרנית.'}, {'q': 'שני רכבים התנגשו. נוסע ברכב א׳ נפגע. נהג רכב ב׳ הוא האשם הבלעדי. ממי יתבע הנוסע?', 'o': ['ממבטח רכב א׳, שבו נסע', 'משני המבטחים בחלקים שווים', 'מקרנית', 'ממבטח רכב ב׳ בלבד, כי נהגו אשם'], 'c': 0, 'e': 'נכון. לפי ס׳ 3(א), כל נוהג אחראי לנזקי הגוף של מי שנסע ברכבו.'}, {'q': 'הולך רגל נפגע בתאונה שבה היו מעורבים שלושה רכבים. כיצד מתחלקת החבות?', 'o': ['רק הרכב שפגע בו פיזית חב', 'כל הנוהגים חבים כלפיו יחד ולחוד, וביניהם בחלקים שווים', 'רק הנהג האשם ביותר', 'לפי מידת האשם של כל נהג'], 'c': 1, 'e': 'נכון. זו לשון ס׳ 3(ב): יחד ולחוד, ובינם לבין עצמם בחלקים שווים.'}, {'q': 'נפגע בתאונת דרכים הרוויח פי חמישה מהשכר הממוצע במשק, ואיבד 100% מכושר השתכרותו. לפי איזו הכנסה יחושב אובדן ההשתכרות?', 'o': ['לפי הכנסתו המלאה', 'עד פי שלושה מהשכר הממוצע במשק, לפי ס׳ 4(א)(1)', 'לפי השכר הממוצע במשק בלבד', 'לפי שכר המינימום'], 'c': 1, 'e': 'נכון. "הכנסה מרבית" היא שילוש השכר הממוצע. אם האובדן חלקי, גם התקרה מופחתת.'}, {'q': 'כיצד נקבע הפיצוי על נזק לא ממוני בתאונת דרכים?', 'o': ['לפי תקרה צמודה ונוסחה בתקנות, שמבוססות בעיקר על שיעור הנכות הרפואית וימי האשפוז', 'אין פיצוי על נזק לא ממוני בתאונות דרכים', 'באומדן חופשי של בית המשפט, בלי תקרה', 'לפי שכרו של הנפגע'], 'c': 0, 'e': 'נכון. ס׳ 4(א)(3) ו־4(ב) והתקנות מ־1976 יוצרים חישוב כמעט מכני עד תקרה.'}, {'q': 'מה קובע ס׳ 68 לחוק חוזה הביטוח לגבי ביטוח אחריות?', 'o': ['שהמבטח חייב לשלם לצד השלישי גם כשהפוליסה אינה מכסה', 'שהצד השלישי אינו רשאי לפנות למבטח', 'שהמבטח רשאי, ולפי דרישת הצד השלישי חייב, לשלם לו את תגמולי הביטוח, וטענות המבטח כלפי המבוטח עומדות לו גם כלפי הצד השלישי', 'שהמבוטח חייב לשלם תחילה, ורק אחר כך לפנות למבטח'], 'c': 2, 'e': 'נכון. זה תוכן הסעיף, כולל ההודעה למבוטח 30 יום מראש והחלת טענות המבטח.'}, {'q': 'מבטח רכוש שילם למבוטח על נזק לביתו שגרם שכן רשלן. מה זכותו של המבטח?', 'o': ['אין לו זכות. התשלום הוא סיכון הביטוח', 'הוא רשאי לתבוע מהשכן סכום כפול', 'הוא רשאי לדרוש מהמבוטח להחזיר את התגמולים', 'זכות תחלוף: הוא נכנס בנעלי המבוטח ותובע את השכן עד גובה מה ששילם, בלי לפגוע ביכולת המבוטח לגבות את יתרת נזקו'], 'c': 3, 'e': 'נכון. ס׳ 62(א)–(ב): הזכות עוברת "כשיעור התגמולים ששילם", והמבוטח קודם ביתרה.'}, {'q': 'אישה גרמה ברשלנות לשריפה בדירת בנה, שהייתה מבוטחת. המבטח פיצה את הבן ומבקש לתבוע את האם בתחלוף. מה הדין?', 'o': ['לא — ס׳ 62(ד) שולל תחלוף נגד מי שמבוטח סביר לא היה תובע בשל קרבת משפחה, כשהנזק לא נגרם בכוונה', 'מותר רק עד מחצית הסכום', 'מותר רק אם האם מבוטחת בביטוח אחריות', 'מותר תמיד'], 'c': 0, 'e': 'נכון. החריג חל על קרבת משפחה ויחסי עובד ומעביד, כשהנזק נגרם שלא בכוונה.'}, {'q': 'עובד נפגע בעבודה, קיבל גמלאות נפגעי עבודה ותובע את המעביד הרשלן. מה דין הגמלאות?', 'o': ['העובד חייב לבחור בין גמלה לבין תביעה', 'מנוכות מהפיצוי לפי ס׳ 82 לפקודה, ואין תחלוף של המוסד נגד המעביד', 'אינן מנוכות ואין תחלוף, והעובד מקבל כפל', 'אינן מנוכות, והמוסד תובע את המעביד בתחלוף'], 'c': 1, 'e': 'נכון. הגמלה מנוכה מהפיצוי שהמעביד חייב, ובכך נמנע כפל בלי תחלוף.'}, {'q': 'נפגע בתאונת דרכים שהיא גם תאונת עבודה קיבל גמלאות מביטוח לאומי. מה דינן בתביעתו נגד מבטח הרכב?', 'o': ['הגמלאות מנוכות מהפיצוי, והמוסד אינו תובע את המבטח, אלא מקבל העברה גלובלית לפי ס׳ 328א', 'הגמלאות אינן מנוכות', 'הנפגע אינו זכאי לגמלאות כי מדובר בתאונת דרכים', 'המוסד תובע את מבטח הרכב בתחלוף פרטני'], 'c': 0, 'e': 'נכון. המבטחים מעבירים אחוז קבוע מדמי הביטוח, ובתביעת הנפגע מנכים את הגמלה (ס׳ 328א(ב)(2)).'}, {'q': 'מה קובע ס׳ 330 לחוק הביטוח הלאומי כשתביעת המוסד ותביעת הנפגע נגד צד שלישי נדונות יחד?', 'o': ['הפיצויים מתחלקים שווה בשווה', 'המוסד לא יקבל יותר מ־75% מסך כל הפיצויים, והנפגע זכאי ליתרה', 'המוסד מקבל את כל הפיצויים עד לגובה הגמלאות', 'הנפגע מקבל תחילה את מלוא נזקו, והמוסד את מה שנשאר'], 'c': 1, 'e': 'נכון. ס׳ 330(א) מבטיח לנפגע לפחות 25% מסך הפיצויים.'}, {'q': 'נפגע שקיבל טיפול רפואי בחינם מקופת החולים תובע את המזיק גם על עלות הטיפול. מה הדין לפי ע״א 5690/98 מוניס נ׳ עאמר?', 'o': ['גם הנפגע וגם הקופה זכאים', 'הנפגע אינו זכאי לתבוע רכיב זה, והקופה כמיטיבה זכאית לחזור אל המזיק', 'הנפגע זכאי לעלות הטיפול', 'אף אחד אינו זכאי, והמזיק פטור'], 'c': 1, 'e': 'נכון. ההלכה המשיכה את אלחדד נ׳ סהר.'}, {'q': 'נהג שראה שוטר חוסם את דרכו האיץ במכוון כדי להימלט, בידיעה שיפגע בשוטר, ופגע בו. מה הסיווג?', 'o': ['תאונת דרכים רגילה, והשוטר מוגבל לחוק הפלת״ד', 'השוטר זכאי רק לגמלה מביטוח לאומי', 'תאונה שנגרמה במתכוון, גם אם המטרה העיקרית הייתה להימלט, ולכן לשוטר שמורה גם עילה לפי פקודת הנזיקין', 'אין לשוטר כל עילה'], 'c': 2, 'e': 'נכון. לפי רע״א 2072/16 פלוני נ׳ שירביט, וס׳ 8(א) משאיר תביעה לפי הפקודה כשאדם אחר גרם לתאונה במתכוון.'}, {'q': 'מה קובע חוק הפלת"ד (1975)?', 'o': ['רשלנות', 'אחריות מוחלטת ללא אשם', 'אחריות חוזית', 'פטור'], 'c': 1, 'e': "ס' 2."}, {'q': 'מהו "ייחוד עילה" (ס\' 8)?', 'o': ['תביעה כפולה', 'הפלת"ד מסלול בלעדי לתאונת דרכים', 'בחירה חופשית', 'ביטול ביטוח'], 'c': 1, 'e': 'חוסם תביעה לפי הפקודה.'}, {'q': 'מהי "קרנית"?', 'o': ['חברת ביטוח רגילה', 'קרן לפיצוי נפגעים ללא מבטח', 'בית משפט', 'רשות מדינה'], 'c': 1, 'e': 'נהג לא מבוטח/לא מזוהה.'}, {'q': 'מה נדרש להוכיח לפי הפלת"ד?', 'o': ['אשם הנהג', 'שנגרם נזק גוף בתאונת דרכים', 'כוונה', 'חוזה'], 'c': 1, 'e': 'אחריות מוחלטת.'}, {'q': 'איזו תכלית מגשים מודל הפלת"ד?', 'o': ['ענישה', 'פיזור הנזק ופיצוי ודאי', 'הרתעה בלבד', 'צמצום ביטוח'], 'c': 1, 'e': 'פיצוי מהיר וודאי.'}]
